   478  static const struct sc_asn1_entry c_asn1_alg_id[3] = {
   479          { "algorithm",  SC_ASN1_OBJECT, SC_ASN1_TAG_OBJECT, 0, NULL, NULL },
   480          { "nullParam",  SC_ASN1_NULL, SC_ASN1_TAG_NULL, SC_ASN1_OPTIONAL, NULL, NULL },
   481          { NULL, 0, 0, 0, NULL, NULL }
