   521  int
   522  sc_asn1_encode_algorithm_id(struct sc_context *ctx, u8 **buf, size_t *len,
   523                              const struct sc_algorithm_id *id,
   524                              int depth)
   525  {
   526          struct sc_asn1_pkcs15_algorithm_info *alg_info;
   527          struct sc_algorithm_id temp_id;
   528          struct sc_asn1_entry asn1_alg_id[3];
   529          u8 *obj = NULL;
   530          size_t obj_len = 0;
   531          int r;
   532          u8 *tmp;
   533
   534          LOG_FUNC_CALLED(ctx);
   535          sc_log(ctx, "type of algorithm to encode: %i", id->algorithm);
   536          alg_info = sc_asn1_get_algorithm_info(id);
   537          if (alg_info == NULL) {
   538                  sc_log(ctx, "Cannot encode unknown algorithm %u", id->algorithm);
   539                  LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);
   540          }
   541
   542          /* Set the oid if not yet given */
   543          if (!sc_valid_oid(&id->oid)) {
   544                  temp_id = *id;
   545                  temp_id.oid = alg_info->oid;
   546                  id = &temp_id;
   547          }
   548
   549          sc_log(ctx, "encode algo %s", sc_dump_oid(&(id->oid)));
   550          sc_copy_asn1_entry(c_asn1_alg_id, asn1_alg_id);
   551          sc_format_asn1_entry(asn1_alg_id + 0, (void *) &id->oid, NULL, 1);
   552
   553          /* no parameters, write NULL tag */
   554          /* If it's EDDSA/XEDDSA, according to RFC8410, params
   555           * MUST be absent */
   556          if (id->algorithm != SC_ALGORITHM_EDDSA &&
   557              id->algorithm != SC_ALGORITHM_XEDDSA &&
   558              (!id->params || !alg_info->encode))
   559                  asn1_alg_id[1].flags |= SC_ASN1_PRESENT;
   560
   561          r = _sc_asn1_encode(ctx, asn1_alg_id, buf, len, depth + 1);
   562          LOG_TEST_RET(ctx, r, "ASN.1 encode of algorithm failed");
   563
   564          /* Encode any parameters */
   565          if (id->params && alg_info->encode) {
   566                  r = alg_info->encode(ctx, id->params, &obj, &obj_len, depth+1);
   567                  if (r < 0) {
   568                          if (obj)
   569                                  free(obj);
   570                          LOG_FUNC_RETURN(ctx, r);
   571                  }
   572          }
   573
   574          if (obj_len) {
   575                  tmp = (u8 *) realloc(*buf, *len + obj_len);
   576                  if (!tmp) {
   577                          free(*buf);
   578                          *buf = NULL;
   579                          free(obj);
   580                          LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
   581                  }
   582                  *buf = tmp;
   583                  memcpy(*buf + *len, obj, obj_len);
   584                  *len += obj_len;
   585                  free(obj);
